<?= view('auth/partials/access_head',['title'=>$title??lang('Auth.forgot_password_heading'),'locale'=>$locale??service('request')->getLocale()]) ?><header class="v4-access-heading"><h2><?= esc(lang('Auth.forgot_password_heading')) ?></h2><p><?= esc(lang('V4.recoveryHelp')) ?></p></header><?php if(session('message')): ?><div class="v4-access-alert" role="status"><?= session('message') ?></div><?php endif; ?><?= form_open('auth/forgot-password',['class'=>'v4-form v4-access-form','novalidate'=>true]) ?><div><label for="identity"><?= esc(lang('Auth.login_identity_label')) ?></label><?= form_input($identity+['class'=>'v4-access-input','placeholder'=>lang('Auth.login_identity_placeholder'),'autocomplete'=>'username','dir'=>'ltr']) ?></div><button type="submit" class="v4-button v4-button--primary"><?= esc(lang('Auth.forgot_password_submit_btn')) ?></button><?= form_close() ?><a class="v4-text-link v4-access-back" href="<?= base_url('auth/login') ?>"><?= esc(lang('V4.backToLogin')) ?></a><?= view('auth/partials/access_footer') ?>